ALTER TABLE public.ride_requests ADD COLUMN provider_owned_operation boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.provider_owned_request_source() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.provider_owned_operation:=false; IF NEW.submitted_via='portal' AND NEW.selected_provider_workspace_id IS NULL AND NOT NEW.is_test AND EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE w.id=NEW.workspace_id AND w.account_type='provider' AND w.status='active' AND NOT w.is_test_account AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) THEN NEW.provider_owned_operation:=true; END IF; RETURN NEW; END $$;
COMMENT ON COLUMN public.ride_requests.provider_owned_operation IS 'Authoritative server-derived normal provider operation; no public review notification or automatic Network distribution. Existing intake_source values preserved.';
CREATE FUNCTION public.create_owned_provider_operation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF NEW.provider_owned_operation AND NOT NEW.is_test AND NEW.trip_kind='passenger' AND NEW.transport_type<>'delivery' THEN tid:=public.promote_ride_request_to_trip(NEW.id); IF tid IS NULL THEN RAISE EXCEPTION 'Owned trip unavailable'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER zzzzz_owned_provider_operation AFTER INSERT ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.create_owned_provider_operation();
CREATE FUNCTION public.invoice_extra_identity_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.facility_agreement_id IS DISTINCT FROM OLD.facility_agreement_id OR NEW.responsible_payer_workspace_id IS DISTINCT FROM OLD.responsible_payer_workspace_id THEN RAISE EXCEPTION 'Invoice payer and agreement are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER invoice_extra_identity_guard BEFORE UPDATE ON public.trip_invoice_documents FOR EACH ROW EXECUTE FUNCTION public.invoice_extra_identity_immutable();
CREATE FUNCTION public.invoice_token_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.expires_at<=now() OR NEW.expires_at>now()+interval '7 days' OR NEW.token_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid secure invoice token'; END IF; ELSE IF NEW.invoice_id IS DISTINCT FROM OLD.invoice_id OR NEW.token_hash IS DISTINCT FROM OLD.token_hash OR NEW.scope IS DISTINCT FROM OLD.scope OR NEW.expires_at IS DISTINCT FROM OLD.expires_at OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Token scope is immutable'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER invoice_token_scope_guard BEFORE INSERT OR UPDATE ON public.trip_invoice_access_tokens FOR EACH ROW EXECUTE FUNCTION public.invoice_token_guard();
CREATE POLICY master_invoice_read ON public.trip_invoice_documents FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY master_invoice_event_read ON public.trip_invoice_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.trip_invoice_access(_invoice uuid,_manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.trip_invoice_documents i JOIN public.workspaces w ON w.id=i.provider_workspace_id WHERE i.id=_invoice AND (public.has_role(auth.uid(),'admin') OR public.can_manage_provider_customer_pricing(w.id) OR (NOT _manage AND ((i.patient_workspace_id IS NOT NULL AND public.patient_request_access(i.request_id)) OR EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces b ON b.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=i.billed_workspace_id AND m.user_id=auth.uid() AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND b.status='active' AND NOT b.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL))))) $$;
CREATE FUNCTION public.reversal_evidence_history_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.reversal_evidence IS DISTINCT FROM OLD.reversal_evidence AND (current_user NOT IN ('postgres','service_role','supabase_admin') OR jsonb_array_length(NEW.reversal_evidence)<jsonb_array_length(OLD.reversal_evidence) OR (SELECT coalesce(jsonb_agg(v ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(NEW.reversal_evidence) WITH ORDINALITY a(v,ord) WHERE ord<=jsonb_array_length(OLD.reversal_evidence)) IS DISTINCT FROM OLD.reversal_evidence) THEN RAISE EXCEPTION 'Reversal evidence is server-owned append-only'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trip_payment_reversal_history BEFORE UPDATE ON public.trip_payments FOR EACH ROW EXECUTE FUNCTION public.reversal_evidence_history_guard();